const partialHeritageNames=new Set(["Mary-Kate Olsen","Ashley Olsen","Karlie Kloss","Robert De Niro","Claire Danes"]);
const legacyLens=(entry:Entry)=>{
 const field=entry.industry.toLowerCase();
 if(/arquitect|ingenier|urban|paisaj/.test(field))return "Su legado se mide en la forma física de la ciudad: edificios, puentes, calles o espacios públicos que modificaron cómo Nueva York funciona y se reconoce.";
 if(/arte|pintura|fotograf|diseño|cine|teatro|música|ópera|literatura|ilustración|moda/.test(field))return "Su relevancia excede el éxito personal: produjo obras, instituciones o lenguajes culturales que encontraron en Nueva York escenario, público y proyección internacional.";
 if(/política|gobierno|derecho|reforma|salud|trabajo|educación|filosofía|sociología/.test(field))return "Su aporte incidió en instituciones, derechos, conocimiento o vida pública; por eso la ficha atiende al efecto verificable de su actuación sobre la ciudad y sus habitantes.";
 if(/banca|comercio|industr|inmobili|ferrocarr|cervec|transporte/.test(field))return "Su actividad dejó infraestructura, empresas, empleo o transformaciones urbanas duraderas, pero la lectura también reconoce las controversias y desigualdades propias de cada época.";
 return "La inclusión responde a una consecuencia identificable para la historia, la cultura o el espacio urbano neoyorquino, no únicamente a fama o genealogía.";
};
const expandedImpact=(entry:Entry)=>{
 const person=personKey(entry.name),life=lifeDates[person]||`figura del siglo ${entry.century}`;
 const milestone=milestoneDates[person]||`Su principal huella neoyorquina se sitúa en el siglo ${entry.century}, en torno a ${entry.place}.`;
 return `${person} (${life}). ${entry.relevance} ${milestone} ${legacyLens(entry)}`;
};
const inclusionReason=(entry:Entry)=>{
 const person=personKey(entry.name);
 if(partialHeritageNames.has(person))return `Representa una herencia ${entry.origin.toLowerCase()} parcial dentro de la Nueva York contemporánea. Su inclusión no equipara ascendencia con inmigración: documenta cómo esa raíz familiar aparece en una trayectoria neoyorquina de alcance público en ${entry.industry.toLowerCase()}.`;
 if(entry.name.includes(" · "))return `Esta ubicación forma parte de una trayectoria con más de un anclaje en la ciudad. Se conserva como punto propio porque permite distinguir la relación de ${person} con ${entry.neighborhood} de sus otras intervenciones o etapas neoyorquinas.`;
 return `Se incluye porque reúne los dos criterios del atlas: una relación biográfica o familiar documentada con ${entry.origin} y una contribución reconocible a Nueva York en ${entry.industry.toLowerCase()}. ${legacyLens(entry)}`;
};
const newYorkConnection=(entry:Entry)=>`La ficha se ancla en ${entry.place}, ${entry.neighborhood}, ${entry.borough}: no es una coordenada decorativa, sino el lugar desde el cual puede leerse su paso por la ciudad. Allí se conecta su biografía con una obra, institución, residencia, escenario o transformación urbana concreta.`;
const totalPeople=new Set(entries.map(e=>personKey(e.name))).size;
